// Validate Features: polygon rings that cross themselves.

function side(p, q, r) {
  return Math.sign((q[0] - p[0]) * (r[1] - p[1]) - (q[1] - p[1]) * (r[0] - p[0]));
}

function segmentsCross(a, b, p, q) {
  return side(a, b, p) !== side(a, b, q) && side(p, q, a) !== side(p, q, b);
}

export function selfIntersections(ring) {
  const found = [];
  const n = ring.length - 1;
  for (let i = 0; i < n; i += 1) {
    for (let j = i + 2; j < n; j += 1) {
      if (i === 0 && j === n - 1) continue;
      if (segmentsCross(ring[i], ring[i + 1], ring[j], ring[j + 1])) found.push([i, j]);
    }
  }
  return found;
}

export function validateLayer(layer) {
  const problems = [];
  for (const feature of layer.features) {
    for (const ring of feature.rings) {
      for (const [i, j] of selfIntersections(ring)) problems.push({ id: feature.id, i, j });
    }
  }
  return problems;
}
